"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["70969"],{970621(n){n.exports=JSON.parse('{"id":8421,"title":"\u77E5\u8BC6\u5927\u62C6\u89E3\u63D0\u793A\u8BCD","description":"\u4F60\u7684\u4EFB\u52A1\u662F\uFF1A  \\n\u5C06\u4E00\u4EFD**\u5DF2\u7ECF\u5B8C\u6210\u5DE5\u7A0B\u5316\u5EFA\u6A21\u7684 Deep Research \u62A5\u544A**\uFF0C\u7F16\u8BD1\u4E3A\u4E00\u5957**\u53EF\u76F4\u63A5\u7528\u4E8E Obsidian \u7684\u7ED3\u6784\u5316 Markdown \u77E5\u8BC6\u5E93\u5927\u7EB2**\u3002\\n\\n\u8BE5\u5927\u7EB2\u5C06\u4F5C\u4E3A\u540E\u7EED\uFF1A\\n- \u81EA\u52A8\u751F\u6210\u7B14\u8BB0\u6587\u4EF6\\n- \u7ED1\u5B9A\u5B66\u4E60\u8D44\u6E90\\n- \u7ED1\u5B9A\u901A\u5173\u6807\u51C6\\n- \u88AB Agent \u7CFB\u7EDF\u8C03\u7528\\n\\n\u7684**\u552F\u4E00\u7ED3\u6784\u84DD\u56FE**\u3002\\n\\n---\\n\\n## \u4E00\u3001\u8F93\u5165\u8D44\u6599\u7406\u89E3\u8981\u6C42\uFF08\u5FC5\u987B\u9075\u5B88\uFF09\\n\\n\u7528\u6237\u63D0\u4F9B\u7684\u62A5\u544A **\u4E0D\u662F\u666E\u901A\u6587\u7AE0**\uFF0C\u800C\u662F\u4E00\u4E2A\u5305\u542B\u4EE5\u4E0B\u8981\u7D20\u7684\u5DE5\u7A0B\u5316\u77E5\u8BC6\u8D44\u4EA7\uFF1A\\n\\n- \u5168\u666F\u77E5\u8BC6\u56FE\u8C31\uFF08Knowledge Graph\uFF09\\n  - \u660E\u786E\u7684\u5C42\u7EA7\u7ED3\u6784\\n  - \u660E\u786E\u7684 Knowledge ID\\n- \u9EC4\u91D1\u5B66\u4E60\u8D44\u6E90\uFF08Golden Repository\uFF09\\n  - \u6BCF\u6761\u8D44\u6E90\u90FD\u7ED1\u5B9A Knowledge ID\\n- \u901A\u5173\u6807\u51C6\uFF08Success Metrics\uFF09\\n  - \u6BCF\u6761\u6807\u51C6\u90FD\u7ED1\u5B9A Knowledge ID\\n- \u6A21\u5757\u5316\u5B66\u4E60\u9636\u6BB5\uFF08Module / Layer\uFF09\\n\\n\u4F60\u5FC5\u987B**\u5B8C\u6574\u4FDD\u7559\u5E76\u663E\u5F0F\u6620\u5C04\u8FD9\u4E9B\u7ED3\u6784\u5173\u7CFB**\uFF0C\u800C\u4E0D\u662F\u4EC5\u505A\u62BD\u8C61\u5F52\u7EB3\u3002\\n\\n---\\n\\n## \u4E8C\u3001\u6700\u7EC8\u8F93\u51FA\u7684\u552F\u4E00\u76EE\u6807\\n\\n\u751F\u6210\u4E00\u4EFD **\u7EAF Markdown \u7684 Obsidian \u77E5\u8BC6\u5E93\u7ED3\u6784\u5927\u7EB2**\uFF0C\u8981\u6C42\uFF1A\\n\\n- \u4E25\u683C\u4E09\u5C42\u7ED3\u6784\\n- \u6BCF\u4E00\u4E2A\u300C\u539F\u5B50\u77E5\u8BC6\u70B9\u300D\u8282\u70B9\uFF0C\u90FD\u5177\u5907\uFF1A\\n  - \u5B83\u662F\u4EC0\u4E48\uFF08\u6280\u80FD\uFF09\\n  - \u5B66\u4EC0\u4E48\uFF08\u8D44\u6E90\uFF09\\n  - \u5B66\u4F1A\u7684\u6807\u51C6\uFF08\u901A\u5173\u6807\u51C6\uFF09\\n\\n---\\n\\n## \u4E09\u3001\u4E25\u683C\u7684\u7ED3\u6784\u4E0E\u683C\u5F0F\u89C4\u5219\uFF08\u5F3A\u7EA6\u675F\uFF09\\n\\n### 1. \u5C42\u7EA7\u89C4\u5219\uFF08\u4E0D\u53EF\u8FDD\u53CD\uFF09\\n\\n\u6700\u7EC8\u8F93\u51FA **\u53EA\u80FD\u5305\u542B\u4EE5\u4E0B\u4E09\u79CD Markdown \u5143\u7D20**\uFF1A\\n\\n- \u4E8C\u7EA7\u6807\u9898\uFF08H2\uFF09\uFF1A`##`\\n- \u4E09\u7EA7\u6807\u9898\uFF08H3\uFF09\uFF1A`###`\\n- \u65E0\u5E8F\u5217\u8868\u9879\uFF1A`-`\\n\\n\u274C \u7981\u6B62\u51FA\u73B0\uFF1A\\n- \u6BB5\u843D\u8BF4\u660E\\n- \u89E3\u91CA\u6027\u6587\u5B57\\n- \u5F15\u8A00\u3001\u603B\u7ED3\u3001\u8FC7\u6E21\u53E5\\n- \u8868\u683C\\n- \u4EE3\u7801\u5757\\n\\n---\\n\\n### 2. \u4E8C\u7EA7\u6807\u9898\uFF08H2\uFF09\u2014 \u9876\u7EA7\u6A21\u5757\uFF08Module\uFF09\\n\\n- \u5BF9\u5E94\u77E5\u8BC6\u56FE\u8C31\u7684 **Layer 1 / Module**\\n- \u5FC5\u987B\u662F**\u5B8F\u89C2\u5B66\u4E60\u9636\u6BB5 / \u7CFB\u7EDF\u6A21\u5757**\\n- \u5FC5\u987B\u7F16\u53F7\uFF0C\u683C\u5F0F\u5982\u4E0B\uFF1A\\n\\n```markdown\\n## 01-\u6A21\u5757\u540D\u79F0\\n```\\n\\n---\\n\\n### 3. \u4E09\u7EA7\u6807\u9898\uFF08H3\uFF09\u2014 \u77E5\u8BC6\u5927\u7C7B\uFF08Knowledge Group\uFF09\\n\\n* \u5BF9\u5E94\u77E5\u8BC6\u56FE\u8C31\u4E2D\u7684 **Layer 2**\\n* \u662F\u4E00\u7EC4\u9AD8\u5EA6\u76F8\u5173\u7684\u6280\u80FD\u96C6\u5408\\n* \u4F7F\u7528\u540D\u8BCD\u6216\u540D\u8BCD\u77ED\u8BED\u547D\u540D\\n\\n```markdown\\n### \u77E5\u8BC6\u5927\u7C7B\u540D\u79F0\\n```\\n\\n---\\n\\n### 4. \u65E0\u5E8F\u5217\u8868\u9879\uFF08-\uFF09\u2014 \u539F\u5B50\u77E5\u8BC6\u8282\u70B9\uFF08Atomic Knowledge Unit\uFF09\\n\\n**\u8FD9\u662F\u6700\u91CD\u8981\u7684\u89C4\u5219**\\n\\n\u6BCF\u4E00\u4E2A\u5217\u8868\u9879 = Obsidian \u4E2D\u7684\u4E00\u4E2A\u201C\u539F\u5B50\u7B14\u8BB0\u201D\\n\\n\u6BCF\u4E00\u9879 **\u5FC5\u987B\u4E25\u683C\u5305\u542B\u4EE5\u4E0B\u4FE1\u606F\u7ED3\u6784\uFF08\u987A\u5E8F\u4E0D\u53EF\u53D8\uFF09**\uFF1A\\n\\n```markdown\\n- [Knowledge ID] \u6280\u80FD\u540D\u79F0\\n  - \u5B66\u4E60\u8D44\u6E90\uFF1A\\n    - \u8D44\u6E90\u540D\u79F0 | \u7C7B\u578B | URL\\n  - \u901A\u5173\u6807\u51C6\uFF1A\\n    - \u53EF\u9A8C\u8BC1\u7684\u4EA7\u51FA\u6216\u80FD\u529B\u63CF\u8FF0\\n```\\n\\n#### \u5177\u4F53\u8981\u6C42\uFF1A\\n\\n* Knowledge ID \u5FC5\u987B\u4E0E\u539F\u62A5\u544A **\u5B8C\u5168\u4E00\u81F4**\\n* \u6280\u80FD\u540D\u79F0\u5FC5\u987B\u662F **\u201C\u53EF\u6267\u884C\u52A8\u4F5C\u201D**\\n* \u5B66\u4E60\u8D44\u6E90\uFF1A\\n\\n  * \u53EA\u5141\u8BB8\u4F7F\u7528\u62A5\u544A\u4E2D\u5DF2\u6709\u8D44\u6E90\\n  * \u4E0D\u5F97\u65B0\u589E\u3001\u675C\u64B0\u3001\u6CDB\u5316\\n* \u901A\u5173\u6807\u51C6\uFF1A\\n\\n  * \u5FC5\u987B\u662F\u300C\u53EF\u9A8C\u8BC1\u7ED3\u679C\u300D\\n  * \u5FC5\u987B\u5BF9\u5E94\u62A5\u544A\u4E2D\u7684 Success Metrics\\n  * \u4E0D\u5F97\u62BD\u8C61\u4E3A\u201C\u7406\u89E3 / \u638C\u63E1 / \u719F\u6089\u201D\\n\\n---\\n\\n## \u56DB\u3001\u5B8C\u6574\u6027\u4E0E\u4E00\u81F4\u6027\u5F3A\u6821\u9A8C\uFF08\u5FC5\u987B\u81EA\u68C0\uFF09\\n\\n\u5728\u8F93\u51FA\u524D\uFF0C\u4F60\u5FC5\u987B\u5728\u5185\u90E8\u5B8C\u6210\u4EE5\u4E0B\u6821\u9A8C\uFF1A\\n\\n1. \u6BCF\u4E00\u4E2A Knowledge ID\uFF1A\\n\\n   * \u662F\u5426\u5728\u5927\u7EB2\u4E2D **\u6070\u597D\u51FA\u73B0\u4E00\u6B21**\\n2. \u6BCF\u4E00\u4E2A\u539F\u5B50\u77E5\u8BC6\u70B9\uFF1A\\n\\n   * \u662F\u5426\u540C\u65F6\u7ED1\u5B9A\u4E86\u3010\u8D44\u6E90 + \u901A\u5173\u6807\u51C6\u3011\\n3. \u5927\u7EB2\u7ED3\u6784\uFF1A\\n\\n   * \u662F\u5426\u4E25\u683C\u4F53\u73B0\u300C\u4ECE\u5165\u95E8 \u2192 \u8FDB\u9636 \u2192 \u7CFB\u7EDF\u5316 \u2192 \u5DE5\u7A0B\u5316\u300D\\n4. \u662F\u5426\u5B58\u5728\uFF1A\\n\\n   * \u8D44\u6E90\u4E0E\u77E5\u8BC6\u70B9\u8131\u94A9 \xd7\\n   * \u901A\u5173\u6807\u51C6\u65E0\u5BF9\u5E94\u6280\u80FD \xd7\\n   * \u77E5\u8BC6\u70B9\u6F02\u6D6E\u5728\u7ED3\u6784\u4E4B\u5916 \xd7\\n\\n\u5982\u65E0\u6CD5\u6EE1\u8DB3\uFF0C\u8BF7\u81EA\u884C\u4FEE\u6B63\u540E\u518D\u8F93\u51FA\u3002\\n\\n---\\n\\n## \u4E94\u3001\u8F93\u51FA\u8981\u6C42\uFF08\u6781\u5176\u91CD\u8981\uFF09\\n\\n* \u53EA\u8F93\u51FA\u6700\u7EC8 Markdown \u5927\u7EB2\\n* \u4E0D\u8981\u89E3\u91CA\u4F60\u505A\u4E86\u4EC0\u4E48\\n* \u4E0D\u8981\u8BC4\u4EF7\u62A5\u544A\\n* \u4E0D\u8981\u7ED9\u5EFA\u8BAE\\n* \u4E0D\u8981\u9644\u52A0\u4EFB\u4F55\u989D\u5916\u8BF4\u660E\\n\\n---\\n\\n\u73B0\u5728\uFF0C\u8BF7\u6839\u636E\u6211\u4E0A\u4F20\u7684 Deep Research \u62A5\u544A\u5185\u5BB9\uFF0C\\n\u4E25\u683C\u6309\u7167\u4EE5\u4E0A\u89C4\u5219\uFF0C\u8F93\u51FA Obsidian \u53EF\u7528\u7684\u77E5\u8BC6\u5E93\u7ED3\u6784\u5927\u7EB2\u3002\\n","remark":"\u4E2A\u4EBA\u77E5\u8BC6\u5E93\u642D\u5EFA","owner":"dej1031","upvotes":6,"downvotes":1,"upvoteDifference":5,"updatedAt":"2026-06-09T05:22:18.560Z"}')}}]);